head.script:
scwin.log = function (msg) {
    var prev = txa_log.getValue() || "";
    txa_log.setValue(prev + msg + "\n");
};
scwin.onpageload = function () {
    scwin.log("=== [최상위] onpageload ===");
    scwin.log("TOP_name = [" + scvar.TOP_name + "] (TOP 기대)");
    scwin.log("키 목록 = " + Object.keys(scvar).join(", "));
};
scwin.btn_check_onclick = function () {
    scwin.log("=== includeFrame scope 공유 결과 ===");
    scwin.log("scvar 키 목록 = " + Object.keys(scvar).join(", "));
    scwin.log("TOP_name = [" + scvar.TOP_name + "] (TOP 기대 - 부모 변수 보존)");
    scwin.log("INC1_name = [" + scvar.INC1_name + "] (ONE 기대 - include1 병합)");
    scwin.log("INC2_name = [" + scvar.INC2_name + "] (TWO 기대 - include2 병합)");
    scwin.log("SHARED_name = [" + scvar.SHARED_name + "] (FROM_INC2 기대 - 나중 파싱 우선)");
    scwin.log("맨이름 window.scvar 잔여 = " + (typeof window["scvar"]) + " (undefined 기대)");
};
